/**
 * Generated by the /ship test coverage audit.
 * Value: protects=editing a channel shows its stored comment opt-in and saves what the switch
 * says; fails_when=openEditDialog drops notifyOnComment, or the switch is bound to another field;
 * why_new=no web test covers the notification channel dialog or useNotificationsData;
 * seam=none; no_claim=API acceptance of the PUT body (authenticatedFetch mocked; jsdom only).
 */
import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import { useNotificationsData } from '../hooks/useNotificationsData';
import { NotificationChannelDialog } from '../components/NotificationChannelDialog';
import type { NotificationChannel } from '../types';

jest.mock('@/lib/api', () => ({ authenticatedFetch: jest.fn() }));
import { authenticatedFetch } from '@/lib/api';

const channel = (over: Partial<NotificationChannel> = {}): NotificationChannel =>
  ({
    id: 'ch-1',
    systemUnderTestId: 'sut-1',
    type: 'slack',
    name: 'perf-alerts',
    webhookUrl: 'https://hooks.slack.com/services/x',
    notifyOnFinished: true,
    notifyOnFailedOnly: false,
    enabled: true,
    useProxy: false,
    createdAt: '2026-11-01T00:00:00Z',
    updatedAt: '2026-11-01T00:00:00Z',
    ...over,
  }) as NotificationChannel;

let hook: ReturnType<typeof useNotificationsData>;
function Harness() {
  hook = useNotificationsData({ systemId: 'sut-1', onSnackbar: jest.fn() });
  return (
    <NotificationChannelDialog
      open={hook.editDialogOpen}
      mode="edit"
      formData={hook.formData}
      saving={hook.saving}
      proxyConfigured={false}
      onFormChange={hook.setFormData}
      onClose={hook.closeDialogs}
      onSubmit={hook.handleEditChannel}
    />
  );
}

const fetchMock = authenticatedFetch as jest.Mock;
const commentSwitch = () =>
  screen.getByLabelText('Notify when test run comments are added') as HTMLInputElement;
const putBody = () => {
  const put = fetchMock.mock.calls.find((c) => c[1]?.method === 'PUT');
  return JSON.parse(put![1].body);
};

beforeEach(() => {
  fetchMock.mockReset();
  fetchMock.mockResolvedValue({ ok: true, json: async () => [] });
});

it.each([
  ['an opted-in channel', true, true, false],
  ['a channel from an API that predates the field', undefined, false, true],
])('editing %s shows its opt-in and saves the toggled value', async (_name, stored, shown, saved) => {
  render(<Harness />);
  await waitFor(() => expect(fetchMock).toHaveBeenCalled());
  act(() => hook.openEditDialog(channel({ notifyOnComment: stored, notifyOnFailedOnly: !shown })));

  expect(commentSwitch().checked).toBe(shown);
  fireEvent.click(commentSwitch());
  fireEvent.click(screen.getByRole('button', { name: 'Save Changes' }));

  await waitFor(() => expect(fetchMock.mock.calls.some((c) => c[1]?.method === 'PUT')).toBe(true));
  expect(putBody()).toMatchObject({ notifyOnComment: saved, notifyOnFailedOnly: !shown });
});
